/** Route files with no PEP call and no recorded reason — the test keeps this empty. */
export const UNEXPLAINED_UNGUARDED: string[] =
  GENERATED_UNGUARDED.filter((route) => !(route in UNGUARDED_ROUTES));

export { GENERATED_UNGUARDED };

/**
 * The inventory narrowed to the modules a deployment has. The committed inventory is generated from the vendor's whole tree, and a starter
 * (docs/phases/35-editions-licensing 11) pulls only its edition's modules, so the coverage screen would list routes that do not exist there.
 * With every module installed (the vendor tree) nothing is dropped. A gap key names its module by its first segment; `app/` keys are the
 * application's own routes and always stay.
 */
export function coverageOfInstalled(installed: ReadonlySet<string>): {
  coverage: CoverageEntry[];
  unguarded: Record<string, { reason: UnguardedReason; note: string }>;
} {
  return {
    coverage: ABAC_COVERAGE.filter((e) => installed.has(e.module)),
    unguarded: Object.fromEntries(Object.entries(UNGUARDED_ROUTES).filter(([route]) => {
      const owner = route.split('/')[0]!;
      return owner === 'app' || installed.has(owner);
    })),
  };
}
